#!/usr/bin/env python3
"""Generate the literal native help pages, or check that they are current."""
import argparse
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
TARGET = ROOT / "src" / "skills_help_pages.metta"
sys.path.insert(0, str(ROOT / "src"))

import skills_help  # noqa: E402


def metta_string(text):
    return '"' + (text.replace("\\", "\\\\").replace('"', '\\"')
                  .replace("\n", "\\n").replace("\r", "\\r")
                  .replace("\t", "\\t")) + '"'


def render():
    lines = [
        "; Generated by scripts/generate_skills_help_pages.py; do not edit.",
        "; Literal data only: lookup and progressive disclosure live in skills_help.metta.",
    ]
    lines += ["(HelpPageV1 %s %s)" % (metta_string(name), metta_string(page))
              for name, page in sorted(skills_help.PAGES.items())]
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render()
    if args.check:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != expected:
            print("%s is stale; regenerate it" % TARGET.relative_to(ROOT))
            return 1
        return 0
    TARGET.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
